#!/usr/bin/env python3
"""Reviewed six-directory hardening and existing V24 STOP install."""
import base64,gzip,hashlib,json,sys,types
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='c76d3042d7a336df76f6f2a2eb7eafae2da8844a9ce7fa2b60437a8326113252':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('v24_stop_io');m.__file__='<reviewed-v24_stop_io>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='bf097864251d8e0e5a9fd16c03bd467627ec307d9e7cd3984e0a81191b7bcca1':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('v24_stop_transform');m.__file__='<reviewed-v24_stop_transform>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='1306f27ad103e40344a5fa637f830199d61c57cf9afcede21daf6ce86888c597':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('native_v24_stop_installer');m.__file__='<reviewed-native_v24_stop_installer>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='103869fe2af37db005779f6579c9d4dc78034007c79f6e428e7f8f5dd610da88':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('admission_state_observer');m.__file__='<reviewed-admission_state_observer>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
raw=gzip.decompress(base64.b64decode('',validate=True))
if hashlib.sha256(raw).hexdigest()!='8e486d9228a0a7c0ba589330b3ae8df74fbd1e5a60ed750a31856ddff9ec0d3b':raise RuntimeError("HOLD_REVIEWED_SOURCE_DIGEST")
m=types.ModuleType('asset_directory_hardening');m.__file__='<reviewed-asset_directory_hardening>';sys.modules[m.__name__]=m
exec(compile(raw,m.__file__,"exec"),m.__dict__)
def main():
    static=sys.modules["native_v24_stop_installer"]
    try:
        static.owner_context()
        observed=sys.modules["admission_state_observer"].observe()
        print("NOX_MAINT_REPAIR="+json.dumps({"kind":"admission_preflight_state","data":observed},separators=(",",":")),flush=True)
        hardened=sys.modules["asset_directory_hardening"].run()
        print("NOX_MAINT_REPAIR="+json.dumps({"kind":"v24_asset_directory_hardening","data":hardened},separators=(",",":")),flush=True)
        if hardened.get("completed") is not True:
            print("NOX_MAINT_REPAIR_COMPLETE=false",flush=True)
            return 2
        return static.entry(rollback=False)
    except BaseException as exc:
        report={"status":"HOLD_"+type(exc).__name__.upper(),"completed":False,"used":False,"accepted":False}
        print("NOX_MAINT_REPAIR="+json.dumps({"kind":"v24_hardening_entry","data":report},separators=(",",":")),flush=True)
        print("NOX_MAINT_REPAIR_COMPLETE=false",flush=True)
        return 2
raise SystemExit(main())
